function dashboard(x){if(x.id==='illinois-basketball-2010')return '<h2>Illinois Fighting Illini · 2011–12</h2><p class="muted">College Hoops 2K8 · Bruce Weber legacy · History begins 2007–08</p><div class="grid"><div class="card"><div class="stat">24–10</div><p>Entering NCAA Tournament</p></div><div class="card"><div class="stat">12–6</div><p>Big Ten · 3rd place</p></div><div class="card"><div class="stat">🏆</div><p>Big Ten Tournament champions</p></div><div class="card"><div class="stat">#8</div><p>East Regional · Baylor next</p></div></div><div class="card"><h3>Illinois Legacy archive</h3><p>Season histories, Bruce Weber, named characters, recruiting, conference history and selected box scores.</p><button class="primary" onclick="changeTab(\'Archive\')">Explore the archive →</button></div>';const elite=x.players.filter(p=>p.dev==='Elite').length;const nil=x.players.reduce((a,p)=>a+(+p.nil||0),0);return '<h2>'+esc(x.name)+' · '+esc(x.season)+'</h2><p class="muted">'+esc(x.sport)+' · Your sports universe headquarters</p><div class="grid">'+[['Roster profiles',x.players.length],['Elite development',elite],['Committed recruits',x.recruits.filter(r=>r.status==='Committed').length],['Known NIL points',nil]].map(([a,b])=>'<div class="card"><div class="stat">'+b+'</div><div class="muted">'+a+'</div></div>').join('')+'</div><div class="card"><h3>Front Office watchlist</h3>'+x.players.filter(p=>p.deal&&p.grade&&rank(p.grade)<rank(p.required)).map(p=>'<p>⚠ '+esc(p.name)+' — '+esc(p.deal)+' ('+esc(p.grade)+' / needs '+esc(p.required)+')</p>').join('')+'<p class="muted">Use Recruiting to manage commitments and the War Room for notes and AI context.</p></div>'}
function rank(s){return {'F':0,'D':1,'D+':2,'C-':3,'C':4,'C+':5,'B-':6,'B':7,'B+':8,'A-':9,'A':10,'A+':11}[s]??-1}
function playerCard(p,i,kind){return '<div class="card"><div class="row"><h3 class="wide">'+(kind==='players'?'<button class="profile-link" onclick="openPlayer('+i+')">'+esc(p.name)+'</button>':esc(p.name))+'</h3><button onclick="editItem(\''+kind+'\','+i+')">Edit</button><button onclick="removeItem(\''+kind+'\','+i+')">×</button></div><div><b>'+esc(p.pos||'')+'</b> '+(p.number!==undefined?'#'+esc(p.number):'')+' · '+esc(p.year||p.status||'')+' '+(p.overall!==undefined?' · '+esc(p.overall)+' OVR':'')+'</div><div>'+[p.dev,p.archetype,p.stars?p.stars+'★':'',p.rank?'#'+p.rank+' position':'',p.nationalRank?'#'+p.nationalRank+' national':'',p.gem?'💎 GEM · Development unconfirmed':''].filter(Boolean).map(t=>'<span class="tag'+(String(t).includes('GEM')?' recruit-gem':'')+'">'+esc(t)+'</span>').join('')+'</div><p class="muted">'+esc(p.size||'')+' · '+esc(p.hometown||'')+'</p>'+(p.nil!==undefined?'<p>NIL: '+esc(p.nil)+' points</p>':'')+((['speed','breakTackle','catching','changeOfDirection','zoneCoverage','tackle'].some(k=>p[k]!==undefined))?'<p>'+[['speed','Speed'],['breakTackle','Break Tackle'],['catching','Catching'],['changeOfDirection','Change of Direction'],['zoneCoverage','Zone Coverage'],['tackle','Tackle']].filter(([k])=>p[k]!==undefined).map(([k,label])=>label+' '+esc(p[k])).join(' · ')+'</p>':'')+(p.deal?'<p>Dealbreaker: '+esc(p.deal)+' · '+esc(p.grade||'?')+' / needs '+esc(p.required||'?')+(p.grade&&p.required?' <b class="'+(rank(p.grade)>=rank(p.required)?'good':'bad')+'">'+(rank(p.grade)>=rank(p.required)?'Satisfied':'At risk')+'</b>':'')+'</p>':'')+(p.notes?'<p>'+esc(p.notes)+'</p>':'')+'</div>'}

const outlookSlots=[['QB','QB'],['RB1','RB'],['RB2','RB'],['WR1','WR'],['WR2','WR'],['WR3','WR'],['TE1','TE'],['TE2','TE'],['LT','LT'],['LG','LG'],['C','C'],['RG','RG'],['RT','RT'],['LE','LE'],['RE','RE'],['EDGE1','EDGE'],['EDGE2','EDGE'],['DT1','DT'],['DT2','DT'],['LOLB','LOLB'],['MLB1','MLB'],['MLB2','MLB'],['ROLB','ROLB'],['CB1','CB'],['CB2','CB'],['CB3','CB'],['FS','FS'],['SS','SS'],['K','K'],['P','P'],['KR','KR'],['PR','PR']];
function eligibility(p){const y=String(p.year||'').toLowerCase();let stage=y.includes('freshman')?0:y.includes('sophomore')?1:y.includes('junior')?2:y.includes('senior')?3:-1;return stage<0?null:stage}
function eligible(p,yr,base){const st=eligibility(p);return st===null||st+(yr-base)<=3}
function yearLabel(p,yr,base){const st=eligibility(p);if(st===null)return 'Class unknown';const n=st+yr-base;return (String(p.year).toLowerCase().includes('rs')?'RS ':'')+['FR','SO','JR','SR'][n]}
function redshirtAdvice(p,yr,base){if(!p||!p.incomingRecruit||yr!==base+1)return '';const advice={'Isaiah Addison':'Redshirt recommended — TE development','Oscar Williams':'Redshirt worth considering — OL development','Siaki Fox':'Redshirt worth considering — safety rotation','Johnny Hepburn':'Redshirt worth considering — RB rotation'};return advice[p.name]||'Consider redshirt if playing time is limited'}
function outlookCandidates(x,yr,base){const roster=x.players||[];const commits=(x.recruits||[]).filter(p=>/committed/i.test(String(p.status||''))&&!roster.some(z=>z.name===p.name));return roster.concat(yr>base?commits.map(p=>({...p,year:'Freshman',incomingRecruit:true,overall:null,dev:'Unconfirmed'})):[])}
function outlookDefault(x,yr,slot){if(x.id!=='washington-2029')return '';const d={'QB':'George Breeze','RB1':'Caleb Scales','RB2':'Danny Waddy','WR1':'Clayton Silver','WR2':'Bobby Jennings','WR3':'David Easy','C':'Brody Callaway','EDGE1':'Jamerson Addington','DT1':'Finau Fox','CB1':'Maurice Nunn','CB2':'Bernie Singletary','FS':'Cameron Hamiel'};const base=Number(x.season)||2029;let p=x.players.find(z=>z.name===d[slot]);if(p&&eligible(p,yr,base))return p.name;if(yr>base){const incoming={'RB1':'Johnny Hepburn','TE1':'Isaiah Addison','C':'Oscar Williams','FS':'Siaki Fox'};const q=(x.recruits||[]).find(z=>z.name===incoming[slot]&&/committed/i.test(String(z.status||'')));if(q&&yr-base<=4)return q.name}return ''}
function outlookPositionMatch(actual,pos){return actual===pos||(pos==='EDGE'&&['LE','RE','DE','EDGE'].includes(actual))||(pos==='LE'&&['LE','DE','EDGE'].includes(actual))||(pos==='RE'&&['RE','DE','EDGE'].includes(actual))||(pos==='MLB'&&['MLB','LB'].includes(actual))||(pos==='LOLB'&&['LOLB','OLB','LB'].includes(actual))||(pos==='ROLB'&&['ROLB','OLB','LB'].includes(actual))||(pos==='KR'&&['KR','RB','WR','CB'].includes(actual))||(pos==='PR'&&['PR','RB','WR','CB'].includes(actual))}
function outlookAuto(x,yr,slot,kind){const base=Number(x.season)||2029;const pos=(outlookSlots.find(z=>z[0]===slot)||[])[1];if(!pos)return '';const used=new Set();for(const [other] of outlookSlots){if(other===slot)break;const chosen=outlookPick(x,yr,other,'starter');if(chosen)used.add(chosen)}const starter=kind==='backup'?outlookPick(x,yr,slot,'starter'):'';if(starter)used.add(starter);const choices=outlookCandidates(x,yr,base).filter(p=>outlookPositionMatch(String(p.pos||'').toUpperCase(),pos)&&eligible(p,yr,p.incomingRecruit?base+1:base)&&!used.has(p.name));choices.sort((a,b)=>Number(b.overall||0)-Number(a.overall||0)||a.name.localeCompare(b.name));return choices[0]?.name||''}
function outlookPick(x,yr,slot,kind){const k=yr+'|'+slot+'|'+kind;if(Object.prototype.hasOwnProperty.call(x.outlook||{},k))return x.outlook[k];if(kind==='starter'){const preset=outlookDefault(x,yr,slot);return preset||outlookAuto(x,yr,slot,kind)}return outlookAuto(x,yr,slot,kind)}
function setOutlook(yr,slot,kind,val){const x=f();x.outlook=x.outlook||{};x.outlook[yr+'|'+slot+'|'+kind]=val;save();render()}
function outlookSelect(x,yr,slot,pos,kind,current){const base=Number(x.season)||2029;const available=outlookCandidates(x,yr,base).filter(p=>{const actual=String(p.pos||'').toUpperCase();const match=outlookPositionMatch(actual,pos);return match&&eligible(p,yr,p.incomingRecruit?base+1:base)});const opts=['<option value="">'+(kind==='starter'?'Unassigned':'No backup')+'</option>'].concat(available.map(p=>'<option value="'+esc(p.name)+'" '+(p.name===current?'selected':'')+'>'+esc(p.name)+'</option>'));if(current&&!available.some(p=>p.name===current))opts.push('<option selected value="'+esc(current)+'">'+esc(current)+' (check eligibility)</option>');return '<select aria-label="'+kind+' '+slot+' '+yr+'" class="'+(kind==='backup'?'backup':'')+'" onchange="setOutlook('+yr+',\''+slot+'\',\''+kind+'\',this.value)">'+opts.join('')+'</select>'}
function toggleDepthEdit(id){const el=document.getElementById(id);if(!el)return;el.classList.toggle('open');if(el.classList.contains('open'))el.querySelector('select')?.focus()}
function depthEditor(x,yr,slot,pos,kind,current){const id='depth-'+yr+'-'+slot+'-'+kind;return '<div class="depth-edit" id="'+id+'">'+outlookSelect(x,yr,slot,pos,kind,current)+'</div>'}
function backupLine(x,yr,slot,pos,name,base){const p=outlookCandidates(x,yr,base).find(z=>z.name===name);const rating=p?projectedOverall(p,yr,p.incomingRecruit?base+1:base):null;const id='depth-'+yr+'-'+slot+'-backup';return '<button type="button" class="backup-line" aria-label="Change backup for '+esc(slot)+' '+yr+'" onclick="toggleDepthEdit(\''+id+'\')"><span style="color:#75658d;font-size:10px">2</span><span class="backup-person"><span class="backup-name">'+esc(p?p.name:'Select backup')+'</span>'+(p?'<span class="backup-class">'+esc(p.incomingRecruit?'Committed recruit · '+['FR','SO','JR','SR'][Math.min(3,yr-base-1)]:yearLabel(p,yr,base))+'</span>':'')+'</span>'+(rating!==null?'<span class="backup-rating" style="background:'+ratingColor(rating,x)+'">'+esc(rating)+'</span>':'')+(p?'<span class="backup-dev" title="'+esc(p.dev||'Unknown development')+'" style="color:'+(String(p.dev||'').toLowerCase()==='elite'?'#9150cf':String(p.dev||'').toLowerCase()==='star'?'#b88715':'#64748b')+'">'+(String(p.dev||'').toLowerCase()==='elite'?'◆':String(p.dev||'').toLowerCase()==='star'?'★':String(p.dev||'').toLowerCase()==='impact'?'▲':'●')+'</span>':'')+(p&&p.transferRisk?'<span class="risk" title="Transfer watch">⚠</span>':'')+'</button>'+depthEditor(x,yr,slot,pos,'backup',name)}
function ratingColor(v,x){if(v===undefined||v===null||v==='')return '#707783';const n=Number(v);return n>=90?'#d629a0':n>=85?'#00bfd0':n>=80?'#d5a526':n>=75?'#a9b3c2':n>=65?'#b87945':'#707783'}
function devMark(d){const v=String(d||'').toLowerCase();return v==='elite'?'<span class="dev-mark"><span class="dev-icon" style="color:#dbb5ff">◆</span> Elite Dev</span>':v==='star'?'<span class="dev-mark"><span class="dev-icon" style="color:#e9c35a">★</span> Star Dev</span>':v==='normal'?'<span class="dev-mark"><span class="dev-icon" style="color:#d0d5df">●</span> Normal Dev</span>':'<span class="dev-mark">Dev unknown</span>'}
function projectedOverall(p,yr,base){if(p.overall===undefined||p.overall===null||p.overall==='')return null;const current=Number(p.overall),years=Math.max(0,yr-base);const rates={elite:5,star:4,impact:3,normal:2};const gain=rates[String(p.dev||'').toLowerCase()]||0;const limit=p.capOverall!==undefined&&p.capOverall!==''?Number(p.capOverall):(p.capped===true||String(p.capped).toLowerCase()==='yes'?current:99);return Math.min(99,limit,current+years*gain)}
function outlook(x){if(/basketball/i.test(x.sport||''))return '<h2>Five-Year Outlook · Basketball</h2><p class="muted">Basketball rotation and scholarship planning will be configured after the starting season and roster are established. Football positions are intentionally hidden.</p>';const base=Number(x.season)||2029;let html='<h2>Five-Year Outlook</h2><p class="muted">Projected team depth chart · '+base+'–'+(base+4)+'. Positions down the left, years across the top. Choose a starter and optional backup for each season.</p><div class="outlook-scroll"><div class="outlook-table"><div class="outlook-head">POSITION</div>'+Array.from({length:5},(_,i)=>'<div class="outlook-head">'+(base+i)+'</div>').join('');for(const [slot,pos] of outlookSlots){html+='<div class="outlook-year">'+esc(slot)+'</div>';for(let yr=base;yr<base+5;yr++){const name=outlookPick(x,yr,slot,'starter');const p=outlookCandidates(x,yr,base).find(p=>p.name===name);const backup=outlookPick(x,yr,slot,'backup');const projected=p?projectedOverall(p,yr,p.incomingRecruit?base+1:base):null;html+='<div class="outlook-cell">'+(p?'<div class="mini-card">'+(projected!==null?'<span class="rating-bubble" style="background:'+ratingColor(projected,x)+'">'+esc(projected)+'</span>':'')+'<small>'+esc(slot)+' · '+esc(p.incomingRecruit?'Committed recruit · '+['FR','SO','JR','SR'][Math.min(3,yr-base-1)]:yearLabel(p,yr,base))+'</small><div class="mini-name">'+esc(p.name)+'</div><div>'+devMark(p.dev)+'</div>'+(redshirtAdvice(p,yr,base)?'<small class="tag" title="Advisory only; eligibility unchanged">'+esc(redshirtAdvice(p,yr,base))+'</small>':'')+'<small>'+(yr===base?'Recorded OVR':'Projected OVR')+'</small></div>':'<div class="mini-card" style="opacity:.42"><small>'+esc(slot)+'</small><div class="mini-name">Open</div><small>Unassigned</small></div>')+'<button type="button" class="depth-change" onclick="toggleDepthEdit(\'depth-'+yr+'-'+slot+'-starter\')">Change starter ▾</button>'+depthEditor(x,yr,slot,pos,'starter',name)+backupLine(x,yr,slot,pos,backup,base)+'</div>'}}return html+'</div></div><p class="outlook-note">Projected OVR: Elite +5, Star +4, Impact +3, Normal +2 per year, up to 99 or a player-specific cap. Projections are estimates, not recorded ratings. Eligibility is estimated from listed class years. Redshirts, transfers, early departures, and role changes can be adjusted manually. Initial assignments are illustrative, not confirmed depth-chart decisions. Hard-committed recruits appear as incoming prospects starting in 2030; they are not yet on the active roster and have no invented overall ratings.</p>'}

function rosterSnapshot(x){const base=Number(x.season)||2029;const order=['QB','RB','FB','WR','TE','LT','LG','C','RG','RT','OL','EDGE','DT','DL','LB','CB','FS','SS','S','K','P'];const players=x.players.map((p,i)=>({p,i})).sort((a,b)=>{const pa=order.indexOf(a.p.pos),pb=order.indexOf(b.p.pos);return (pa<0?99:pa)-(pb<0?99:pb)||a.p.name.localeCompare(b.p.name)});let html='<div class="row"><h2 class="wide">Roster Snapshot</h2><button onclick="changeTab(\'Five-Year Outlook\')">Detailed outlook</button></div><p class="muted">Players down the left, seasons across the top. Tap a name or rating to open the player profile.</p><div class="snapshot-scroll"><div class="snapshot-grid"><div class="snapshot-head snapshot-player-head">PLAYER</div>'+Array.from({length:5},(_,i)=>'<div class="snapshot-head">'+(base+i)+'</div>').join('');let last='';for(const {p,i} of players){const pos=p.pos||'OTHER';if(pos!==last){html+='<div class="snapshot-group">'+esc(pos)+'</div>';last=pos}html+='<button class="snapshot-player" onclick="openPlayer('+i+')"><span class="snapshot-player-name">'+esc(p.name)+'</span><small>'+esc(pos)+(p.number?' · #'+esc(p.number):'')+'</small></button>';for(let j=0;j<5;j++){const yr=base+j,active=eligible(p,yr,base),o=active?projectedOverall(p,yr,base):null;html+='<div class="snapshot-rating-cell">'+(active?'<button class="snapshot-rating" onclick="openPlayer('+i+')" title="'+esc(p.name+' · '+yr)+'" style="background:'+(o===null?'#707783':ratingColor(o,x))+'">'+(o===null?'—':o)+'<span class="snapshot-trait">'+(String(p.dev||'').toLowerCase()==='elite'?'◆':String(p.dev||'').toLowerCase()==='star'?'★':String(p.dev||'').toLowerCase()==='impact'?'▲':String(p.dev||'').toLowerCase()==='normal'?'●':'')+'</span></button>':'<span class="snapshot-empty">—</span>')+'</div>'}}return html+'</div></div><p class="muted">◆ Elite · ★ Star · ▲ Impact · ● Normal. Ratings after the current season are projections. A dash means the player is past estimated eligibility; unknown ratings show —.</p>'}
function openPlayer(i){const x=f(),p=x.players[i];if(!p)return;history.replaceState(null,'',location.pathname+location.search+'#player='+encodeURIComponent(p.name));document.getElementById('view').innerHTML=playerProfile(p,i,x)}
function profileField(label,value){return '<div class="profile-field"><small>'+esc(label)+'</small><strong>'+esc(value===undefined||value===null||value===''?'Not recorded':value)+'</strong></div>'}
function profileSection(title,body){return '<section class="card profile-section"><h3>'+title+'</h3>'+body+'</section>'}
function playerProfile(p,i,x){const base=Number(x.season)||2029;const isGeorge=p.name==='George Breeze'&&x.id==='washington-2029';const recruiting=p.recruiting||{};const historyItems=p.history||[];const stats=p.stats||[];const badges=p.badges||[];const attrs=p.attributes||{};const details=isGeorge?{...{'Throw Power':96,'Deep Accuracy':90,'Speed':90,'Break Sack':83,'Agility':85,'Throw on Run':82},...attrs}:attrs;const star=recruiting.stars??(isGeorge?5:p.stars);const intro='<div class="profile-hero"><div><span class="profile-kicker">'+esc(x.name)+' / '+esc(x.season)+'</span><h2>'+esc(p.name)+'</h2><p>'+esc(p.pos||'Player')+(p.number?' · #'+esc(p.number):'')+' · '+esc(p.year||'Class unknown')+'</p><p>'+esc(p.hometown||'Hometown not recorded')+'</p></div><div class="profile-big-ovr" style="background:'+ratingColor(p.overall,x)+'">'+esc(p.overall??'—')+'<small>OVR</small></div></div>';let h='<div class="row"><button onclick="closePlayer()">← Back</button><span class="wide"></span><button onclick="copyPlayerLink()">Copy link</button><button onclick="editItem(\'players\','+i+')">Edit</button></div>'+intro+'<div class="profile-grid">'+profileField('Development',p.dev)+profileField('Height / weight',p.size)+profileField('Archetype',p.archetype)+profileField('NIL points',p.nil)+profileField('Transfer watch',p.transferRisk||'Not flagged')+'</div>';
h+=profileSection('Player attributes','<div class="profile-grid">'+Object.entries(details).map(([k,v])=>profileField(k,v)).join('')+(Object.keys(details).length?'':'<p class="muted">No attributes uploaded yet.</p>')+'</div>');
h+=profileSection('Recruiting history','<div class="profile-grid">'+profileField('Recruit rating',star?star+' stars':'Not recorded')+profileField('High school / origin',recruiting.highSchool||p.hometown)+profileField('Recruiting class',recruiting.classYear)+profileField('National rank',recruiting.nationalRank)+profileField('Position rank',recruiting.positionRank)+profileField('Recruiting coach',recruiting.coach)+profileField('Commitment',recruiting.commitment)+'</div>');
h+=profileSection('Transfers & career timeline',historyItems.length?historyItems.map(z=>'<div class="profile-event"><b>'+esc(z.season||z.date||'Date unknown')+'</b> · '+esc(z.type||'Event')+' — '+esc(z.description||'')+'</div>').join(''):'<p class="muted">No transfers or career events recorded. That does not confirm a player has never transferred.</p>');
h+=profileSection('Season statistics',stats.length?'<div class="profile-grid">'+stats.map(z=>profileField(z.label||z.season||'Stat',z.value)).join('')+'</div>':'<p class="muted">Season stats not uploaded yet.</p>');
h+=profileSection('Badges & honors',badges.length?badges.map(z=>'<span class="tag">'+esc(typeof z==='string'?z:z.name||'Badge')+'</span>').join(''):'<p class="muted">Badges and honors can be added later.</p>');
h+=profileSection('Scouting notes','<p>'+esc(p.notes||'No notes yet.')+'</p>'+(p.deal?'<p>Dealbreaker: '+esc(p.deal)+'</p>':''));
h+='<p class="muted">Profiles use your locally saved franchise data. The link can open this player on your device, but uploaded edits are not publicly synchronized yet.</p>';h+=personNews(x,{name:p.name,record:p})+personConnections(x,{name:p.name,record:p});return h}
function closePlayer(){history.replaceState(null,'',location.pathname+location.search);render()}
function copyPlayerLink(){navigator.clipboard.writeText(location.href).then(()=>alert('Link copied. Public sharing of custom data requires cloud publishing.')).catch(()=>alert('Unable to copy link.'))}


function coachingStaff(x){const staff=x.staff||[];return '<div class="row"><h2 class="wide">Coaching Staff · '+esc(x.season)+'</h2><button class="primary" onclick="editCoach(-1)">+ Coach</button></div><p class="muted">Build your coaching tree across seasons. Staff profiles can track recruiting connections, career moves and franchise storylines.</p><div class="grid">'+staff.map((c,i)=>'<div class="card coach-card"><div class="row"><div class="wide"><small class="coach-label">'+esc(c.role||'Coach')+'</small><h3>'+esc(c.name)+'</h3></div><button onclick="editCoach('+i+')">Edit</button></div><div class="coach-meta"><span class="coach-prestige">'+esc(c.prestige||'—')+' <small>Prestige</small></span><span class="coach-level">LVL '+esc(c.level??'—')+'</span></div><div class="profile-grid">'+profileField('Archetype',c.archetype)+profileField('Alma mater',c.almaMater)+profileField('Offense',c.offense)+profileField('Defense',c.defense)+'</div>'+(c.mainCharacter?'<p><span class="tag">★ Main character</span></p>':'')+(c.notes?'<p>'+esc(c.notes)+'</p>':'')+'<p class="muted">'+(c.history?.length?esc(c.history.length)+' career timeline entries · '+esc(c.history[0].years)+'–'+esc(c.history[c.history.length-1].years):'Career timeline not entered')+'</p><button class="primary" onclick="openCoach('+i+')">View full career timeline →</button></div>').join('')+'</div>'}
function coachIndex(x){const all=[...(x.staff||[]).map((c,i)=>({c,i,archive:false})),...(x.coachIndex||[]).map((c,i)=>({c,i,archive:true}))];return '<div class="row"><h2 class="wide">Coach Index</h2><button onclick="changeTab(\'Coaching Staff\')">Current staff</button></div><p class="muted">Permanent coaching profiles across your dynasty, including coaches who never worked at Washington.</p><div class="grid">'+all.map(({c,i,archive})=>'<div class="card coach-card"><small class="coach-label">'+esc(archive?'Historical coach':'Washington staff')+'</small><h3>'+esc(c.name)+'</h3><p>'+esc(c.role||'Coach')+' · '+esc(c.team||(archive?'':'Washington'))+'</p><button class="primary" onclick="openCoach('+i+','+archive+')">View profile</button></div>').join('')+'</div>'}
function openCoach(i,archive=false){const x=f(),c=archive?(x.coachIndex||[])[i]:(x.staff||[])[i];if(!c)return;const history=c.history||[];const recruits=x.players.filter(p=>p.recruiting&&p.recruiting.coach===c.name);const peers=[];history.forEach(h=>{if(h.headCoach)peers.push({label:'Head Coach',name:h.headCoach,years:h.years,team:h.team});if(h.offensiveCoordinator)peers.push({label:'Offensive Coordinator',name:h.offensiveCoordinator,years:h.years,team:h.team})});const all=[...(x.staff||[]).map((c,i)=>({c,i,archive:false})),...(x.coachIndex||[]).map((c,i)=>({c,i,archive:true}))];const connections=peers.map(peer=>{const match=all.find(z=>z.c.name===peer.name);return '<div class="profile-event"><b>'+esc(peer.years)+' · '+esc(peer.team)+'</b><p>'+esc(peer.label)+': '+(match?'<button class="profile-link" onclick="openCoach('+match.i+','+match.archive+')">'+esc(peer.name)+'</button>':esc(peer.name))+'</p></div>'}).join('');document.getElementById('view').innerHTML='<div class="row"><button onclick="changeTab(\'Coach Index\')">← Coach Index</button><span class="wide"></span>'+(!archive?'<button onclick="editCoach('+i+')">Edit</button>':'')+'</div><div class="profile-hero"><div><span class="profile-kicker">'+esc(c.role||'Coach')+' · '+esc(c.team||'Washington')+'</span><h2>'+esc(c.name)+'</h2><p>'+esc(c.archetype||'')+' · '+esc(c.almaMater||'')+'</p></div><div class="coach-profile-prestige">'+esc(c.prestige||'—')+'<small>Prestige</small></div></div><div class="profile-grid">'+profileField('Level',c.level)+profileField('Offensive scheme',c.offense)+profileField('Defensive scheme',c.defense)+profileField('Alma mater',c.almaMater)+'</div>'+profileSection('Biography',c.biography?'<p>'+esc(c.biography)+'</p>':'No biography recorded')+profileSection('Coaching career & history',history.length?history.map(h=>'<div class="profile-event"><b>'+esc(h.years||'Year unknown')+'</b> · '+esc(h.team||'')+' · '+esc(h.role||'')+(h.record?'<p>Overall '+esc(h.record)+' · Conference '+esc(h.conferenceRecord||'—')+'</p>':'')+(h.conferenceTitle?'<p>'+esc(h.conferenceTitle)+'</p>':'')+(h.postseason?'<p>'+esc(h.postseason)+'</p>':'')+'</div>').join(''):'<p class="muted">Career timeline not entered yet.</p>')+profileSection('Coaching tree & connections',connections||'<p class="muted">No coaching connections recorded yet.</p>')+profileSection('Recruiting connections',recruits.length?recruits.map(p=>'<p><button class="profile-link" onclick="openPlayer('+x.players.indexOf(p)+')">'+esc(p.name)+'</button></p>').join(''):'<p class="muted">No linked recruits yet.</p>')+personNews(x,{name:c.name,record:c})+personConnections(x,{name:c.name,record:c})+profileSection('Dynasty notes','<p>'+esc(c.notes||'No notes yet.')+'</p>')}
function editCoach(i){const c=i<0?{}:f().staff[i];const fields=[['name','Name'],['role','Staff role'],['season','Season'],['prestige','Prestige'],['almaMater','Alma mater'],['level','Level'],['archetype','Archetype'],['offense','Offensive scheme'],['defense','Defensive scheme'],['notes','Notes']];document.getElementById('view').innerHTML='<h2>'+(i<0?'Add coach':'Edit '+esc(c.name))+'</h2><form class="card" onsubmit="saveCoach(event,'+i+')"><div class="grid">'+fields.map(([key,label])=>'<label>'+label+'<input name="'+key+'" value="'+esc(c[key]??'')+'"></label>').join('')+'</div><p><label><input type="checkbox" name="mainCharacter" '+(c.mainCharacter?'checked':'')+'> Main character</label></p><button class="primary">Save coach</button> <button type="button" onclick="render()">Cancel</button></form>'}
function saveCoach(e,i){e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(!String(values.name||'').trim()){alert('Name required');return}const old=i<0?{}:f().staff[i];const coach={...old,...values,level:values.level===''?undefined:Number(values.level),mainCharacter:!!values.mainCharacter};if(i<0){coach.id='coach-'+Date.now();f().staff.push(coach)}else f().staff[i]=coach;save();tab='Coaching Staff';render()}

function roster(x){return '<div class="row"><h2 class="wide">Roster · '+x.players.length+'</h2><button class="primary" onclick="editItem(\'players\',-1)">+ Player</button></div><input id="filter" placeholder="Search players or positions" oninput="filterCards()" style="width:100%;margin-bottom:12px"><div id="cards" class="grid">'+x.players.map((p,i)=>playerCard(p,i,'players')).join('')+'</div>'}
function filterCards(){const q=document.getElementById('filter').value.toLowerCase();document.querySelectorAll('#cards>.card').forEach(el=>el.style.display=el.textContent.toLowerCase().includes(q)?'':'none')}
function recruiting(x){return '<div class="row"><h2 class="wide">Recruiting board</h2><button class="primary" onclick="editItem(\'recruits\',-1)">+ Recruit</button></div><div class="grid">'+x.recruits.map((p,i)=>playerCard(p,i,'recruits')).join('')+'</div>'}
const fields=['name','pos','number','year','overall','dev','archetype','hometown','size','nil','stars','rank','nationalRank','gem','speed','breakTackle','catching','changeOfDirection','zoneCoverage','tackle','status','deal','grade','required','capped','capOverall','transferRisk','notes'];function editItem(kind,i){const p=i<0?{}:f()[kind][i];document.getElementById('view').innerHTML='<h2>'+(i<0?'Add':'Edit')+' '+(kind==='players'?'player':'recruit')+'</h2><div class="card"><form id="editor" onsubmit="submitItem(event,\''+kind+'\','+i+')"><div class="grid">'+fields.map(k=>'<div><label>'+k.replace(/\b\w/g,c=>c.toUpperCase())+'</label>'+(k==='notes'?'<textarea name="'+k+'">'+esc(p[k]||'')+'</textarea>':'<input name="'+k+'" value="'+esc(p[k]??'')+'">')+'</div>').join('')+'</div><p><button class="primary">Save</button> <button type="button" onclick="render()">Cancel</button></p></form></div>'}
function submitItem(e,kind,i){e.preventDefault();const raw=Object.fromEntries(new FormData(e.target));const p={};Object.entries(raw).forEach(([k,v])=>{if(v.trim()!=='')p[k]=['overall','nil','stars','rank','nationalRank','speed','breakTackle','catching','changeOfDirection','zoneCoverage','tackle','capOverall'].includes(k)?Number(v):v});if(!p.name){alert('Name required');return}if(kind==='recruits')p.gem=['true','yes','1','gem','green'].includes(String(p.gem||'').toLowerCase());if(i<0)f()[kind].push(p);else f()[kind][i]={...f()[kind][i],...p};save();render()}
function removeItem(kind,i){if(!confirm('Delete this entry?'))return;f()[kind].splice(i,1);save();render()}
function warroom(x){return '<h2>The War Room</h2><div class="card"><p>Record scouting, storylines, trade ideas, and season notes.</p><textarea id="newnote" placeholder="What happened? What should your front office remember?"></textarea><p><button class="primary" onclick="addNote()">Save note</button> <button onclick="copyContext()">Copy AI context</button></p><p class="muted">Copy AI context and paste into ChatGPT to discuss this franchise. Live AI chat is not yet connected.</p></div>'+x.notes.slice().reverse().map(n=>'<div class="card"><small class="muted">'+esc(n.date)+'</small><p>'+esc(n.text)+'</p></div>').join('')}
function addNote(){const t=document.getElementById('newnote').value.trim();if(!t)return;f().notes.push({date:new Date().toLocaleDateString(),text:t});save();render()}
function context(){const x=f();return 'Franchise HQ — '+x.name+' ('+x.sport+', '+x.season+')\nROSTER\n'+x.players.map(p=>JSON.stringify(p)).join('\n')+'\nRECRUITING\n'+x.recruits.map(p=>JSON.stringify(p)).join('\n')+'\nNOTES\n'+x.notes.map(n=>n.date+': '+n.text).join('\n')}
function copyContext(){navigator.clipboard.writeText(context()).then(()=>alert('Copied franchise context')).catch(()=>{const t=document.createElement('textarea');t.value=context();document.body.append(t);t.select();document.execCommand('copy');t.remove();alert('Copied')})}

function illinoisLegacy(x){const d=window.ILLINOIS_LEGACY;if(!d)return '<h2>Illinois Legacy</h2><p>Archive is loading. Refresh this page.</p>';const active=Number(x.legacyTab||0);const tabs=d.tabs;const t=tabs[Math.max(0,Math.min(active,tabs.length-1))];const sections=[['Overview',0],['2011–12',1],['2010–11',5],['Recruiting',10],['Characters',11],['Big Ten',17]];return '<h2>Illinois Legacy · College Hoops 2K8</h2><p class="muted">Original archive from your Google Doc. NCAA opener vs Baylor is pending. <a href="'+d.source+'" target="_blank" rel="noopener">Source document</a></p><div class="row">'+sections.map(([name,i])=>'<button '+(active===i?'class="active" ':'')+'onclick="setIllinoisTab('+i+')">'+name+'</button>').join('')+'</div><div class="card"><label for="legacySection">Archive page</label><select id="legacySection" onchange="setIllinoisTab(Number(this.value))" style="width:100%">'+tabs.map((p,i)=>'<option value="'+i+'" '+(i===active?'selected':'')+'>'+esc(p.title)+'</option>').join('')+'</select></div><div class="card legacy-article"><h2>'+esc(t.title)+'</h2>'+t.blocks.map((b,i)=>'<p class="'+(i===0?'legacy-lead':'')+'">'+esc(b)+'</p>').join('')+'</div>'}
function setIllinoisTab(i){f().legacyTab=i;save();render()}

function scribeArticles(x){return Array.isArray(x.scribeArticles)?x.scribeArticles:[]}

function mediaPublications(x){if(!Array.isArray(x.publications))x.publications=[];for(const p of [{id:'firebird',name:'Firebird',voice:'Fast-moving, personality-driven coverage of the franchise universe.',brand:'Digital-first sports feed',description:'News, reactions and ongoing storylines.'},{id:'saturday-scribe',name:'Saturday Scribe',voice:'Thoughtful, narrative-driven long-form sports journalism.',brand:'Classic sports newspaper',description:'Features, game stories and historical reporting.'}])if(!x.publications.some(z=>z.id===p.id))x.publications.push({...p});return x.publications}
function mediaWriters(x){if(!Array.isArray(x.mediaPersonalities))x.mediaPersonalities=[];return x.mediaPersonalities}
function mediaStoryList(x,pub){return scribeArticles(x).filter(a=>!pub||((a.publicationId||'saturday-scribe')===pub)).slice().sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
function mediaWriterName(x,id){return mediaWriters(x).find(w=>w.id===id)?.name||'Unassigned writer'}

function storyArt(a,large){const label=esc((a.category||'COLLEGE FOOTBALL').toUpperCase());const color=(a.category==='Coaching'?'#243b59':a.category==='Recruiting'?'#6a342d':'#304b45');return '<div style="background:linear-gradient(135deg,'+color+',#151d2e);color:#fff;min-height:'+(large?'250':'140')+'px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;padding:18px;text-align:center"><div style="font-family:Georgia,serif;font-weight:900;letter-spacing:.11em;font-size:'+(large?'30':'20')+'px">SATURDAY<br>SCRIBE</div><small style="letter-spacing:.15em;opacity:.8">'+label+'</small></div>'}
function storyClick(franchiseId,id,back){return 'onclick="openScribeStory('+JSON.stringify(franchiseId).replace(/"/g,'&quot;')+','+JSON.stringify(id).replace(/"/g,'&quot;')+','+JSON.stringify(back||'Saturday Scribe').replace(/"/g,'&quot;')+')"'}

function writerProfile(franchiseId,writerId,back){const owner=data.find(z=>z.id===franchiseId);if(!owner)return;const w=mediaWriters(owner).find(z=>z.id===writerId);if(!w)return;const stories=mediaStoryList(owner).filter(a=>a.writerId===writerId),pubs=mediaPublications(owner),pub=pubs.find(p=>p.id===w.publicationId),returnTab=['Firebird','Saturday Scribe','Publications','Media Personalities'].includes(back)?back:'Media Personalities';document.getElementById('view').innerHTML='<button onclick="changeTab(\''+returnTab+'\')">← Back to '+returnTab+'</button><section class="card" style="margin-top:16px"><small class="muted">WRITER PROFILE</small><h1 style="font-family:Georgia,serif">'+esc(w.name)+'</h1><p>'+esc(w.role||'Journalist')+'</p><p>'+esc(w.bio||'')+'</p><p><strong>Editorial voice:</strong> '+esc(w.voice||'Not recorded')+'</p><p><strong>Publication:</strong> '+esc(pub?.name||'Unassigned')+'</p></section>'+(Array.isArray(w.career)&&w.career.length?'<h2>Career Timeline</h2><div class="grid">'+w.career.map(c=>'<div class="card"><strong>'+esc(c.year||'')+'</strong><p>'+esc(c.publication||'')+' · '+esc(c.role||'')+'</p></div>').join('')+'</div>':'')+'<h2>More from '+esc(w.name)+'</h2>'+(stories.length?'<div class="grid">'+stories.map(a=>'<article class="card" style="cursor:pointer" '+storyClick(owner.id,a.id,returnTab)+'><small class="muted">'+esc(a.date||'')+' · '+esc(a.category||'News')+'</small><h3>'+esc(a.headline||'')+'</h3><p>'+esc(a.deck||'')+'</p><small>Read article →</small></article>').join('')+'</div>':'<p class="muted">No published articles in this archive yet.</p>')}
function newsroomFilters(x,pub){const stories=mediaStoryList(x,pub),years=[...new Set(stories.map(a=>String(a.date||'').slice(0,4)).filter(Boolean))].sort().reverse(),categories=[...new Set(stories.map(a=>a.category||'News'))].sort(),writers=[...new Set(stories.map(a=>a.writerId).filter(Boolean))];return '<div class="card" style="display:flex;gap:12px;flex-wrap:wrap;align-items:end;margin:16px 0"><label>Year<select id="newsYear" onchange="filterNewsroom()"><option value="">All years</option>'+years.map(v=>'<option>'+esc(v)+'</option>').join('')+'</select></label><label>Category<select id="newsCategory" onchange="filterNewsroom()"><option value="">All categories</option>'+categories.map(v=>'<option>'+esc(v)+'</option>').join('')+'</select></label><label>Writer<select id="newsWriter" onchange="filterNewsroom()"><option value="">All writers</option>'+writers.map(v=>'<option value="'+esc(v)+'">'+esc(mediaWriterName(x,v))+'</option>').join('')+'</select></label></div>'}
function filterNewsroom(){const year=document.getElementById('newsYear')?.value||'',cat=document.getElementById('newsCategory')?.value||'',writer=document.getElementById('newsWriter')?.value||'';document.querySelectorAll('[data-news-story]').forEach(el=>{el.style.display=(!year||el.dataset.year===year)&&(!cat||el.dataset.category===cat)&&(!writer||el.dataset.writer===writer)?'':'none'})}

function universePeople(x){return [...(x.players||[]).map((p,i)=>({kind:'player',name:p.name,index:i,record:p})),...(x.historicalPlayers||[]).map((p,i)=>({kind:'historical',name:p.name,index:i,record:p})),...(x.staff||[]).map((p,i)=>({kind:'coach',name:p.name,index:i,record:p})),...(x.coachIndex||[]).map((p,i)=>({kind:'archivedCoach',name:p.name,index:i,record:p}))]}
function personAction(person){return person.kind==='player'?'openPlayer('+person.index+')':person.kind==='historical'?'openHistoricalPlayer('+person.index+')':'openCoach('+person.index+','+(person.kind==='archivedCoach')+')'}
function personCards(x,people){return '<div class="grid">'+people.map(p=>'<button class="card" style="text-align:left;cursor:pointer;width:100%" onclick="'+personAction(p)+'"><small class="muted">'+esc(p.kind==='coach'||p.kind==='archivedCoach'?'COACH':'PLAYER')+' · '+esc(p.record.team||p.record.season||x.name)+'</small><h3>'+esc(p.name)+'</h3><p>'+esc(p.record.role||p.record.pos||p.record.position||'View profile')+'</p><small>Explore profile →</small></button>').join('')+'</div>'}
function personConnections(x,person){const others=universePeople(x).filter(p=>p.name!==person.name),personText=[person.name,person.record.notes||'',person.record.biography||'',JSON.stringify(person.record.history||[]),person.record.recruiting?.coach||''].join(' ').toLowerCase();const linked=others.filter(p=>{const n=p.name.toLowerCase();return n.length>=5&&personText.includes(n)||[p.record.notes||'',p.record.biography||'',JSON.stringify(p.record.history||[]),p.record.recruiting?.coach||''].join(' ').toLowerCase().includes(person.name.toLowerCase())}).slice(0,12);return profileSection('Connections',linked.length?personCards(x,linked):'<p class="muted">No documented personal connections yet.</p>')}
function personNews(x,person){const name=person.name.toLowerCase(),last=name.split(' ').pop().replace(/[^a-z]/g,'');const stories=mediaStoryList(x).filter(a=>{const t=[a.headline,a.deck,a.body].join(' ').toLowerCase();return t.includes(name)}).slice(0,12);return profileSection('News & coverage',stories.length?'<div class="grid">'+stories.map(a=>'<button class="card" style="text-align:left;cursor:pointer" onclick="openScribeStory('+JSON.stringify(x.id).replace(/"/g,'&quot;')+','+JSON.stringify(a.id).replace(/"/g,'&quot;')+',\'Universe Timeline\')"><small class="muted">'+esc(a.date||'')+' · '+esc(a.category||'Story')+'</small><h3>'+esc(a.headline||'')+'</h3><small>Read article →</small></button>').join('')+'</div>':'<p class="muted">No articles mentioning this person yet.</p>')}
function eventPeople(x,e){const t=[e.title,e.body].join(' ').toLowerCase();return universePeople(x).filter(p=>{const n=p.name.toLowerCase(),last=n.split(' ').pop().replace(/[^a-z]/g,'');return t.includes(n)}).slice(0,10)}

function universeTimeline(x){const events=(x.universeHistory||[]).slice().sort((a,b)=>String(b.year||'').localeCompare(String(a.year||'')));const years=[...new Set(events.map(e=>String(e.year||'Unknown')))];return '<div class="row"><h2 class="wide">Universe Timeline</h2><button onclick="changeTab(\'Archive\')">Full Archive</button></div><p class="muted">Established events from this franchise universe, with related historical coverage.</p>'+(events.length?years.map(y=>'<section style="margin:22px 0"><h2 style="font-family:Georgia,serif;border-bottom:2px solid var(--primary);padding-bottom:8px">'+esc(y)+'</h2><div style="display:grid;gap:12px">'+events.filter(e=>String(e.year||'Unknown')===y).map(e=>{const related=mediaStoryList(x).filter(a=>{const words=(e.title+' '+e.body).toLowerCase();const headline=(a.headline||'').toLowerCase();return ['eastern michigan','washington','oregon','creighton','bjornson','byu','ohio state'].some(t=>words.includes(t)&&headline.includes(t))}).slice(0,3);return '<article class="card"><small class="muted">'+esc(e.type||'Historical event')+'</small><h3>'+esc(e.title||'')+'</h3><p>'+esc(e.body||'')+'</p>'+(eventPeople(x,e).length?'<h4>People in this story</h4>'+personCards(x,eventPeople(x,e)):'')+(related.length?'<strong>Related coverage</strong><div style="display:grid;gap:8px;margin-top:8px">'+related.map(a=>'<button style="text-align:left" onclick="openScribeStory('+JSON.stringify(x.id).replace(/\"/g,'&quot;')+','+JSON.stringify(a.id).replace(/\"/g,'&quot;')+',\'Universe Timeline\')">'+esc(a.headline||'')+' →</button>').join('')+'</div>':'')+'</article>'}).join('')+'</div></section>').join(''):'<div class="card">No historical events recorded for this franchise yet.</div>')}

function mediaStoryCards(x,pub){const stories=mediaStoryList(x,pub);return stories.length?newsroomFilters(x,pub)+'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:16px">'+stories.map(a=>'<article data-news-story data-year="'+esc(String(a.date||'').slice(0,4))+'" data-category="'+esc(a.category||'News')+'" data-writer="'+esc(a.writerId||'')+'" class="card" style="padding:0;overflow:hidden;cursor:pointer" '+storyClick(x.id,a.id,'Publications')+'>'+storyArt(a,false)+'<div style="padding:16px"><small class="muted">'+esc(a.category||'Feature')+' · '+esc(a.date||'')+'</small><h3>'+esc(a.headline||'Untitled')+'</h3><p>'+esc(a.deck||'')+'</p><small class="muted">By '+esc(mediaWriterName(x,a.writerId))+'</small></div></article>').join('')+'</div>':'<div class="card"><p>No stories published yet.</p></div>'}
function publicationPage(x,id){const p=mediaPublications(x).find(z=>z.id===id);if(!p)return publications(x);return '<div class="card" style="border-top:6px solid var(--primary)"><small class="muted">'+esc(p.brand||'Franchise HQ media')+'</small><h1 style="font-family:Georgia,serif;font-size:clamp(30px,6vw,52px);margin:8px 0">'+esc(p.name)+'</h1><p>'+esc(p.description||'')+'</p><p class="muted">Editorial voice: '+esc(p.voice||'Not yet defined')+'</p></div><div class="row"><h2 class="wide">Latest Stories</h2><button class="primary" onclick="scribeEditById(null,'+JSON.stringify(id).replace(/"/g,'&quot;')+')">+ Write a story</button></div>'+mediaStoryCards(x,id)}
function saturdayScribe(x){const stories=mediaStoryList(x,'saturday-scribe');const lead=stories[0],rest=stories.slice(1);return '<header style="padding:24px 0;border-bottom:4px solid #1e293b;text-align:center"><small style="letter-spacing:.2em">THE HOME OF COLLEGE FOOTBALL</small><h1 style="font-family:Georgia,serif;font-size:clamp(35px,8vw,64px);letter-spacing:-.05em;margin:8px 0">SATURDAY SCRIBE</h1><small>NEWS · ANALYSIS · RECRUITING · THE COACHING CAROUSEL</small></header><div class="row" style="margin:20px 0"><h2 class="wide">Top Stories</h2><button class="primary" onclick="scribeEditById(null,\'saturday-scribe\')">+ Write a story</button></div>'+(lead?'<article class="card" style="padding:0;overflow:hidden;cursor:pointer" '+storyClick(x.id,lead.id)+'>'+storyArt(lead,true)+'<div style="padding:20px"><small class="muted">TOP STORY · '+esc(lead.category||'Feature')+' · '+esc(lead.date||'')+'</small><h2 style="font-family:Georgia,serif;font-size:clamp(25px,5vw,38px);line-height:1.14;margin:12px 0">'+esc(lead.headline)+'</h2><p>'+esc(lead.deck||'')+'</p><small class="muted">By '+esc(mediaWriterName(x,lead.writerId))+' · Read story →</small></div></article>':'<div class="card">No stories yet. Publish the first Saturday Scribe feature.</div>')+(rest.length?'<h2 style="margin-top:26px">More Headlines</h2><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px">'+rest.map(a=>'<article class="card" style="padding:0;overflow:hidden;cursor:pointer" '+storyClick(x.id,a.id)+'>'+storyArt(a,false)+'<div style="padding:16px"><small class="muted">'+esc(a.category||'News')+' · '+esc(a.date||'')+'</small><h3>'+esc(a.headline)+'</h3><p>'+esc(a.deck||'')+'</p><small>Read story →</small></div></article>').join('')+'</div>':'')}
function openScribeStory(franchiseId,storyId,back){const owner=data.find(z=>z.id===franchiseId),a=owner&&scribeArticles(owner).find(z=>z.id===storyId);if(!a)return;const writer=mediaWriters(owner).find(w=>w.id===a.writerId),related=mediaStoryList(owner).filter(z=>z.id!==a.id);const byWriter=related.filter(z=>z.writerId===a.writerId);const recommendations=[...byWriter,...related.filter(z=>z.writerId!==a.writerId)].slice(0,4);const returnTab=['Publications','Firebird','Saturday Scribe','Media Personalities','Universe Timeline'].includes(back)?back:'Saturday Scribe';document.getElementById('view').innerHTML='<div class="row"><button onclick="changeTab(\''+returnTab+'\')">← Back to '+returnTab+'</button></div><article style="max-width:850px;margin:auto"><small class="muted">'+esc(a.category||'Feature')+' · '+esc(a.date||'')+'</small><h1 style="font-family:Georgia,serif;font-size:clamp(30px,6vw,48px);line-height:1.12">'+esc(a.headline||'')+'</h1><p style="font-size:1.2em">'+esc(a.deck||'')+'</p><p class="muted">By <strong>'+esc(mediaWriterName(owner,a.writerId))+'</strong></p>'+storyArt(a,true)+'<div class="card" style="margin-top:18px"><p style="white-space:pre-wrap;line-height:1.85;font-size:1.08em">'+esc(a.body||'')+'</p></div>'+(writer?'<section class="card" style="margin-top:20px;cursor:pointer" onclick="writerProfile('+JSON.stringify(owner.id).replace(/\"/g,'&quot;')+','+JSON.stringify(writer.id).replace(/\"/g,'&quot;')+','+JSON.stringify(returnTab).replace(/\"/g,'&quot;')+')"><small class="muted">ABOUT THE WRITER · VIEW PROFILE →</small><h3>'+esc(writer.name)+'</h3><p>'+esc(writer.role||'Journalist')+'</p><p>'+esc(writer.bio||'')+'</p><small>'+byWriter.length+' more stories by this writer</small></section>':'')+'<h2 style="margin-top:28px">Related Reading</h2>'+(recommendations.length?'<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px">'+recommendations.map(z=>'<article class="card" style="cursor:pointer;padding:0;overflow:hidden" '+storyClick(owner.id,z.id,returnTab)+'>'+storyArt(z,false)+'<div style="padding:14px"><small class="muted">'+esc(z.category||'News')+'</small><h3>'+esc(z.headline||'')+'</h3><small>By '+esc(mediaWriterName(owner,z.writerId))+'</small></div></article>').join('')+'</div>':'<p class="muted">More stories will appear here as this publication grows.</p>')+'</article>'}
function firebird(x){
const entries=[x].flatMap(fr=>{
 const articles=scribeArticles(fr).map(a=>({kind:'article',...a,franchiseName:fr.name,franchiseId:fr.id}));
 const headlines=(fr.nationalHeadlines||[]).map(h=>({kind:'headline',...h,franchiseName:fr.name,franchiseId:fr.id}));
 const posts=(fr.firebirdPosts||[]).map(p=>({kind:'post',...p,franchiseName:fr.name,franchiseId:fr.id}));
 return [...articles,...headlines,...posts];
}).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')));
const cards=entries.map(a=>{
 const owner=data.find(fr=>fr.id===a.franchiseId)||x;
 const isArticle=a.kind==='article',isPost=a.kind==='post';
 const handle=isPost?(a.handle||a.author||'Fan'):isArticle?mediaWriterName(owner,a.writerId):'Firebird News Desk';
 const intro=isArticle?((a.deck||a.headline||'').slice(0,260)):isPost?(a.text||'').slice(0,280):((a.headline||'')+' — '+(a.deck||'')).slice(0,280);
 const linkedStory=isArticle?a:(isPost&&a.writerId?scribeArticles(owner).find(st=>st.writerId===a.writerId&&st.id==='scribe-2027-bjornson-washington'):null);
 const link=linkedStory?'<button style="display:block;width:100%;text-align:left;margin-top:12px;padding:12px;border:1px solid #d4d4d8;border-radius:10px;background:var(--soft);color:inherit" onclick="openFirebirdStory('+JSON.stringify(a.franchiseId).replace(/"/g,'&quot;')+','+JSON.stringify(linkedStory.id).replace(/"/g,'&quot;')+')"><small class="muted">SATURDAY SCRIBE · ARTICLE</small><strong style="display:block;margin-top:5px">'+esc(linkedStory.headline)+'</strong><small>Read full story →</small></button>':'';
 return '<article class="card" style="padding:16px;border-radius:14px"><small class="muted"><strong>'+esc(handle)+'</strong> · '+esc(a.date||'')+' · '+esc(a.franchiseName)+'</small><p style="white-space:pre-wrap;line-height:1.5;margin:10px 0">'+esc(intro)+'</p>'+link+'</article>';
}).join('');
return '<div class="card" style="background:linear-gradient(125deg,#5e1b16,#b44420);color:white;padding:22px"><small>FRANCHISE HQ SOCIAL</small><h1 style="font-family:Georgia,serif;font-size:clamp(34px,7vw,58px);margin:5px 0">FIREBIRD</h1><p>Every voice. Every headline. One sports universe.</p></div><div class="row"><h2 class="wide">The feed</h2><button class="primary" onclick="nationalHeadlineEdit()">+ National headline</button></div><p class="muted">Short posts and linked stories from your fictional sports universe.</p>'+(cards?'<div style="display:grid;gap:10px;max-width:740px">'+cards+'</div>':'<div class="card">The feed is quiet.</div>');
}
function openFirebirdStory(franchiseId,storyId){openScribeStory(franchiseId,storyId,'Firebird')}
function nationalHeadlineEdit(){document.getElementById('view').innerHTML='<h2>National news desk</h2><p class="muted">Record the events of your fictional sports universe.</p><form class="card" onsubmit="nationalHeadlineSave(event)"><label>Headline<input name="headline" required></label><label>Category<select name="category"><option>Heisman Trophy</option><option>National Championship</option><option>All-Americans</option><option>National Awards</option><option>Rankings</option><option>Conference Championship</option><option>Breaking News</option><option>Other</option></select></label><label>Date<input type="date" name="date" required value="'+new Date().toISOString().slice(0,10)+'"></label><label>Summary<textarea name="deck" rows="3"></textarea></label><label>Details<textarea name="body" rows="6"></textarea></label><div class="row"><button class="primary">Publish headline</button><button type="button" onclick="changeTab(\'Firebird\')">Cancel</button></div></form>'}
function nationalHeadlineSave(e){e.preventDefault();const x=f();if(!Array.isArray(x.nationalHeadlines))x.nationalHeadlines=[];x.nationalHeadlines.push({id:'headline-'+Date.now(),...Object.fromEntries(new FormData(e.target))});save();changeTab('Firebird')}
function publications(x){const pubs=mediaPublications(x);return '<div class="row"><h2 class="wide">Publications</h2><button class="primary" onclick="publicationEdit()">+ Add publication</button></div><p class="muted">Each outlet has its own identity, voice, writers and stories. Open an outlet to read its feed.</p><div class="grid">'+pubs.map(p=>'<div class="card"><small class="muted">'+esc(p.brand||'Media outlet')+'</small><h2>'+esc(p.name)+'</h2><p>'+esc(p.description||'')+'</p><p class="muted">'+mediaStoryList(x,p.id).length+' stories · '+esc(p.voice||'Voice not set')+'</p><div class="row"><button class="primary" onclick="openPublication('+JSON.stringify(p.id).replace(/"/g,'&quot;')+')">Open publication</button><button onclick="publicationEdit('+JSON.stringify(p.id).replace(/"/g,'&quot;')+')">Edit profile</button></div></div>').join('')+'</div>'}
function openPublication(id){document.getElementById('view').innerHTML='<div class="row"><button onclick="changeTab(\'Publications\')">← Publications</button></div>'+publicationPage(f(),id)}
function publicationEdit(id){const x=f(),p=mediaPublications(x).find(z=>z.id===id)||{};document.getElementById('view').innerHTML='<h2>Publication profile</h2><form class="card" onsubmit="publicationSave(event,'+JSON.stringify(id||null).replace(/"/g,'&quot;')+')"><label>Name<input required name="name" value="'+esc(p.name||'')+'"></label><label>Brand / format<input name="brand" value="'+esc(p.brand||'')+'"></label><label>Description<textarea name="description" rows="3">'+esc(p.description||'')+'</textarea></label><label>Editorial voice<textarea name="voice" rows="4">'+esc(p.voice||'')+'</textarea></label><div class="row"><button class="primary">Save publication</button><button type="button" onclick="changeTab(\'Publications\')">Cancel</button></div></form>'}
function publicationSave(e,id){e.preventDefault();const x=f(),list=mediaPublications(x),v=Object.fromEntries(new FormData(e.target)),p=list.find(z=>z.id===id);if(p)Object.assign(p,v);else list.push({id:'publication-'+Date.now(),...v});save();changeTab('Publications')}
function mediaPersonalities(x){const writers=mediaWriters(x);return '<div class="row"><h2 class="wide">Media Personalities</h2><button class="primary" onclick="writerEdit()">+ Add media member</button></div><p class="muted">Reporters, columnists, analysts and hosts. Writers can contribute to multiple publications.</p>'+(writers.length?'<div class="grid">'+writers.map(w=>'<div class="card"><small class="muted">'+esc(w.role||'Media personality')+'</small><h3><button class="profile-link" onclick="writerProfile('+JSON.stringify(x.id).replace(/\"/g,'&quot;')+','+JSON.stringify(w.id).replace(/\"/g,'&quot;')+',\'Media Personalities\')">'+esc(w.name)+'</button></h3><p>'+esc(w.bio||'')+'</p><p class="muted">Voice: '+esc(w.voice||'Not yet defined')+'</p><p class="muted">'+scribeArticles(x).filter(a=>a.writerId===w.id).length+' bylined stories</p><button onclick="writerEdit('+JSON.stringify(w.id).replace(/"/g,'&quot;')+')">Edit profile</button></div>').join('')+'</div>':'<div class="card"><p>No media personalities yet. Add a writer before publishing your first bylined story.</p></div>')}
function writerEdit(id){const w=mediaWriters(f()).find(z=>z.id===id)||{};document.getElementById('view').innerHTML='<h2>Media personality</h2><form class="card" onsubmit="writerSave(event,'+JSON.stringify(id||null).replace(/"/g,'&quot;')+')"><label>Name<input required name="name" value="'+esc(w.name||'')+'"></label><label>Role<input name="role" placeholder="Reporter, columnist, analyst…" value="'+esc(w.role||'')+'"></label><label>Biography<textarea name="bio" rows="4">'+esc(w.bio||'')+'</textarea></label><label>Writing style / voice<textarea name="voice" rows="4">'+esc(w.voice||'')+'</textarea></label><div class="row"><button class="primary">Save media member</button><button type="button" onclick="changeTab(\'Media Personalities\')">Cancel</button></div></form>'}
function writerSave(e,id){e.preventDefault();const x=f(),list=mediaWriters(x),v=Object.fromEntries(new FormData(e.target)),w=list.find(z=>z.id===id);if(w)Object.assign(w,v);else list.push({id:'writer-'+Date.now(),...v});save();changeTab('Media Personalities')}
function scribeEdit(i){const a=mediaStoryList(f())[i];scribeEditById(a?.id||null)}
function scribeEditById(id,publicationId){const x=f(),a=scribeArticles(x).find(z=>z.id===id)||{},writers=mediaWriters(x),pubs=mediaPublications(x);if(!writers.length){alert('Create a media personality first so every story has a byline.');changeTab('Media Personalities');return}const options=['Game Recap','Recruiting','Coaching','Feature','Conference','Postseason','Opinion'];document.getElementById('view').innerHTML='<div class="row"><h2 class="wide">'+(id?'Edit story':'New story')+'</h2><button onclick="changeTab(\'Publications\')">Cancel</button></div><form class="card" onsubmit="scribeSaveById(event,'+JSON.stringify(id||null).replace(/"/g,'&quot;')+')"><label>Publication<select name="publicationId">'+pubs.map(p=>'<option value="'+esc(p.id)+'" '+((a.publicationId||publicationId||'saturday-scribe')===p.id?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select></label><label>Byline<select required name="writerId">'+writers.map(w=>'<option value="'+esc(w.id)+'" '+(a.writerId===w.id?'selected':'')+'>'+esc(w.name)+'</option>').join('')+'</select></label><label>Headline<input required name="headline" value="'+esc(a.headline||'')+'"></label><label>Section<select name="category">'+options.map(o=>'<option '+(o===a.category?'selected':'')+'>'+o+'</option>').join('')+'</select></label><label>Publication date<input type="date" name="date" value="'+esc(a.date||new Date().toISOString().slice(0,10))+'"></label><label>Subheadline<input name="deck" value="'+esc(a.deck||'')+'"></label><label>Story<textarea name="body" rows="12" required>'+esc(a.body||'')+'</textarea></label><button class="primary">Publish story</button></form>'}
function scribeSaveById(e,id){e.preventDefault();const x=f();x.scribeArticles=scribeArticles(x);const v=Object.fromEntries(new FormData(e.target));if(!mediaWriters(x).some(w=>w.id===v.writerId)){alert('Choose a valid writer');return}const old=x.scribeArticles.find(a=>a.id===id);if(old)Object.assign(old,v);else x.scribeArticles.push({id:'story-'+Date.now(),...v});save();changeTab(v.publicationId==='firebird'?'Firebird':v.publicationId==='saturday-scribe'?'Saturday Scribe':'Publications')}
function scribeSave(e,i){const a=mediaStoryList(f())[i];scribeSaveById(e,a?.id||null)}
function scribeDeleteById(id){const x=f(),a=scribeArticles(x).find(z=>z.id===id);if(!a||!confirm('Delete this story?'))return;x.scribeArticles=x.scribeArticles.filter(z=>z!==a);save();render()}
function scribeDelete(i){const a=mediaStoryList(f())[i];if(a)scribeDeleteById(a.id)}
function archive(x){if(x.id==='illinois-basketball-2010')return illinoisLegacy(x);const legends=x.historicalPlayers||[];const events=(x.universeHistory||[]).slice().sort((a,b)=>String(a.year||'').localeCompare(String(b.year||'')));const rules=x.universeRules||[];const foundation='<h3>Universe Foundation</h3><div class="grid">'+events.map(h=>'<div class="card"><small class="muted">'+esc(h.year||'')+' · '+esc(h.type||'History')+'</small><h3>'+esc(h.title||'')+'</h3><p>'+esc(h.body||'')+'</p></div>').join('')+'</div><h3>Established Universe Rules</h3><div class="grid">'+rules.map(z=>'<div class="card"><h3>'+esc(z.title||z.name||'Rule')+'</h3><p>'+esc(z.body||z.description||'')+'</p></div>').join('')+'</div>';return '<h2>The Archive</h2><div class="card"><h3>'+esc(x.name)+' · '+esc(x.season)+'</h3><p>'+x.players.length+' current roster profiles · '+legends.length+' historical players · '+x.recruits.length+' recruiting records · '+x.notes.length+' notes</p></div><div class="row"><button class="primary" onclick="changeTab(\'Universe Timeline\')">Explore Universe Timeline →</button></div>'+foundation+'<h3>Historical Players & Awards</h3><div class="grid">'+(legends.length?legends.map((p,i)=>'<div class="card"><small class="coach-label">'+esc(p.season)+' · '+esc(p.team)+'</small><h3>'+esc(p.name)+'</h3><p>'+esc(p.role||p.position||'')+'</p>'+((p.awards||[]).map(a=>'<span class="tag">🏆 '+esc(a.name)+'</span>').join(''))+'<p class="muted">'+esc(p.notes||'')+'</p><button onclick="openHistoricalPlayer('+i+')">View historical profile</button></div>').join(''):'<p class="muted">No historical players recorded yet.</p>')+'</div>'}function openHistoricalPlayer(i){const p=(f().historicalPlayers||[])[i];if(!p)return;document.getElementById('view').innerHTML='<button onclick="changeTab(\'Archive\')">← Archive</button><div class="profile-hero"><div><span class="profile-kicker">'+esc(p.team)+' · '+esc(p.season)+'</span><h2>'+esc(p.name)+'</h2><p>'+esc(p.role||p.position||'')+'</p></div></div>'+profileSection('Awards',(p.awards||[]).map(a=>'<p>🏆 '+esc(a.season)+' '+esc(a.name)+' — '+esc(a.description||'')+'</p>').join(''))+profileSection('Career background','<div class="profile-grid">'+profileField('Previous position',p.previousPosition)+profileField('Transfer',p.transfer?'Yes':'Not recorded')+profileField('Transferred from',p.transferFrom||'Unknown')+'</div>')+profileSection('Historical notes','<p>'+esc(p.notes||'')+'</p>')+personNews(f(),{name:p.name,record:p})+personConnections(f(),{name:p.name,record:p})}
function setRating(k,v){const x=f();x.ratingThresholds=x.ratingThresholds||{};x.ratingThresholds[k]=Number(v);save();render()}function setColor(k,v){if(!/^#[0-9a-f]{6}$/i.test(v))return;f().colors=f().colors||{};f().colors[k]=v;save();render()}function settings(x){const c=x.colors||(x.id==='washington-2029'?{primary:'#4b2e83',accent:'#b7a57a'}:{primary:'#234b84',accent:'#d1d5db'});return '<h2>Settings & backups</h2><div class="card"><h3>OVR rating colors</h3><p class="muted">90–99 Magenta · 85–89 Electric teal · 80–84 Gold · 75–79 Silver · 65–74 Bronze · 0–64 Gray. This palette is used across player cards.</p></div><div class="card"><h3>Franchise colors</h3><div class="row"><label>Primary <input type="color" value="'+esc(c.primary)+'" onchange="setColor(\'primary\',this.value)"></label><label>Accent <input type="color" value="'+esc(c.accent)+'" onchange="setColor(\'accent\',this.value)"></label></div><p class="muted">Colors follow the selected franchise.</p></div><div class="card"><p><b>Storage:</b> Saved locally by default. To sync across devices, sign in using Private cloud sync above and choose which save to use.</p><button class="primary" onclick="backup()">Export all franchises</button> <label>Import backup JSON</label><input type="file" accept=".json,application/json" onchange="restore(event)"><p class="muted">Import replaces all local franchises. Export a backup first.</p></div>'}
function backup(){const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='franchise-hq-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}
async function restore(e){try{const x=JSON.parse(await e.target.files[0].text());if(!Array.isArray(x)||!x.every(z=>z.id&&z.name&&Array.isArray(z.players)))throw Error('Invalid backup');if(!confirm('Replace all local franchises with this backup?'))return;data=x;selected=data[0].id;save();render()}catch(err){alert(err.message)}}

